local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[401904]=b({e[17034],401904,11,66,120,"「わたあめとたこ焼き、どっちを先に食べようか～。あ！　あっちにはたい焼きもあるよ～！　……雀士さん、見て見て～、金魚すくいだ～！　わぁ～い！　今夜全部見て回る時間足りるかな～。」",200019,2,"deco/character/xiaoniaoyouchutian_YY",false,false,1,1,false,false,false,"0",2028,841,396,789,380,2679,2944,789,538,2679,1261,false,false,false,false,false,false,false,false,false,false,false,false,"xiaoniaoyouchutian_yy"},h)g[401905]=b({e[17034],401905,14,43,121,"「偉大なるフリット・ドーナツの名の下に命じる、召喚に応えたまえ―って、あれれ～？　なんか属性すら違う子が出てきちゃった～……えっと……な、汝は、この魂天戦争に参加する覚悟は出来ておるか～？」",200019,2,"deco/character/xiaoniaoyouchutian_YSJ",false,false,false,false,false,false,false,"0",1909,883,380,155,31,3272,3364,340,572,2902,1261,false,false,false,false,false,false,false,false,false,false,false,false,"xiaoniaoyouchutian_ysj"},h)g[401906]=b({e[23034],401906,9,35,122,"「お日様までなんだかふわふわ……ふぁ～……寝ちゃいそう～……。ダメダメ、これじゃせっかくの雀士さんと二人きりの時間がもったいない。あ、そうだ！　よかったら一緒にアイスクリーム食べませんか～？」",200019,2,"deco/character/xiaoniaoyouchutian_SY",false,false,false,false,false,false,false,false,false,false,false,"120,-380,1","100,0,1","100,0,1",1614,1161,397,896,44,2792,2669,896,859,2792,1261,1,4513,5000,2154,3162,5333,5333,10666,5333,12000,8000,5333,"xiaoniaoyouchutian_sy"},h)g[401907]=b({e[17045],401907,18,67,123,"「ブランコが一番高い所まで上がった時にお願い事をすると、十二神様たちの耳に早く届くんだって～。\nあ、でも、一緒にいたいな～ってお願いなら、神様じゃなくて、あなたが叶えてくれるよね～！ えへへ～」",200019,2,"deco/character/xiaoniaoyouchutian_xl",false,false,false,false,false,false,false,"0",1,2351,5000,1106,2148,6666,10333,8000,10000,17000,10000,6666,"xiaoniaoyouchutian_xl"},h)g[402001]=b({e[46059],402001,false,68,124,false,200020,false,"deco/character/402001",302002,60,1,false,false,false,300,false,false,false,false,false,false,false,false,"0,-230,1.1","-80,80,1","-50,60,1",false,false,false,"-80,80,1","0,80,1",false,false,false,1845,1035,390,1682,849,1161,1780,1682,849,1161,1141,0},h)g[402002]=b({e[17034],402002,1,